import React from 'react';
import { useParams, Link } from 'react-router-dom';
import bunnycloud from './assets/bunnycloud.png'; // Adjust the path as necessary

const items = [
  { id: 1, image: bunnycloud, title: 'Bunny Cloud', description: 'A fluffy bunny cloud.' },
  { id: 2, image: bunnycloud, title: 'Bunny Cloud 2', description: 'Another fluffy bunny cloud.' },
  { id: 3, image: bunnycloud, title: 'Bunny Cloud 3', description: 'A cute and fluffy bunny cloud.' },
  // Add more items as necessary
];

const ArtPiece = () => {
  const { id } = useParams();
  const itemId = parseInt(id);
  const item = items.find((piece) => piece.id === itemId);

  if (!item) {
    return <div>Art piece not found!</div>;
  }

  const nextItem = items.find((piece) => piece.id === itemId + 1);
  const prevItem = items.find((piece) => piece.id === itemId - 1);

  return (
    <div className="art-piece-detail">
      <img src={item.image} alt={item.title} className="art-piece-image" />
      <h1>{item.title}</h1>
      <p>{item.description}</p>

      <div className="navigation-buttons">
        {prevItem && (
          <Link to={`/art/${prevItem.id}`} className="nav-button">
            Previous: {prevItem.title}
          </Link>
        )}
        {nextItem && (
          <Link to={`/art/${nextItem.id}`} className="nav-button">
            Next: {nextItem.title}
          </Link>
        )}
      </div>

      {/* Back to Gallery Button */}
      <Link to="/gallery" className="back-button">
        Back to Gallery
      </Link>
    </div>
  );
};

export default ArtPiece;
